import { AxisScale } from '@visx/axis';

import { mapValueToDomain } from '../../../../core/components/threshold-bar/functions/map-value-to-domain.js';
import { ThresholdIndicatorData } from '../../../../core/components/threshold-bar/indicators/ThresholdIndicator.js';
import { ThresholdData } from '../../../../core/types/thresholds.js';
import { isStatic } from '../../../../core/types/type-guards.js';
import { isVertical } from '../../../functions/layout.js';
import { Layout } from '../../../types/categorical-bar-chart.js';

export const transformThresholdIntoIndicatorByLayout = (
  data: ThresholdData,
  scale: AxisScale<number>,
  layout: Layout,
  size: number,
): ThresholdIndicatorData[] => {
  const valueMin = mapValueToDomain(
    isStatic(data) ? data.value : data.min,
    scale,
  );
  const valueMax = mapValueToDomain(
    isStatic(data) ? data.value : data.max,
    scale,
  );

  if (isVertical(layout)) {
    return [
      {
        x0: 0,
        x1: 0,
        y0: valueMin,
        y1: valueMax,
      },
      {
        x0: size,
        x1: size,
        y0: valueMin,
        y1: valueMax,
      },
    ];
  }

  return [
    {
      x0: valueMin,
      x1: valueMax,
      y0: 0,
      y1: 0,
    },
    {
      x0: valueMin,
      x1: valueMax,
      y0: size,
      y1: size,
    },
  ];
};
